/* 合成大奶娃 · 排行榜（2026-09-30 修复：新账号 + 分数上限 + 未来时间戳过滤） */
(function () {
'use strict';
var API = 'https://tinywebdb.appinventor.space/api';
var USER = 'jackieqi';
var SECRET = '829fec11';
var PREFIX = 'dnw_';
var NAME_KEY = 'danaiwa.name';
var DEFAULT_NAME = '默认用户';
var MUTE_MIN_GAP = 3000;
var MAX_SCORE = 50000;
var SCAN_PAGES = 2;
var WINDOW = 20;
var $ = function (id) { return document.getElementById(id); };
function post(params) {
var body = new URLSearchParams();
body.set('user', USER);
body.set('secret', SECRET);
for (var k in params) body.set(k, params[k]);
var once = function () {
return fetch(API, { method: 'POST', body: body }).then(function (res) {
if (!res.ok) throw new Error('HTTP ' + res.status);
return res.text();
}).then(function (text) {
var s = (text || '').trim();
if (!s) return {};
try { return JSON.parse(s); } catch (e) { throw new Error('服务器返回看不懂：' + s.slice(0, 60)); }
});
};
return once().catch(function (err) {
return new Promise(function (r) { setTimeout(r, 700); }).then(once).catch(function () { throw err; });
});
}
function addScore(name, score) {
var tag = PREFIX + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 6);
var value = JSON.stringify({ n: name, s: score, t: Date.now() });
return post({ action: 'update', tag: tag, value: value });
}
function scan() {
var out = {};
var no = 1, page = 0;
function step() {
return post({ action: 'search', no: String(no), count: '100', tag: PREFIX, type: 'both' }).then(function (obj) {
for (var k in obj) {
if (k.indexOf(PREFIX) === 0 && typeof obj[k] === 'string') out[k] = obj[k];
}
page++;
if (page < SCAN_PAGES) { no += 100; return step(); }
return out;
});
}
return step();
}
function timeOf(tag, rec) {
var t = Number(rec && rec.t);
if (isFinite(t) && t > 0) return t;
var mid = String(tag).split('_')[1] || '';
if (/^\d{12,}$/.test(mid)) return Number(mid);
var s = parseInt(mid, 36);
return isFinite(s) ? s : 0;
}
function fetchTop() {
return scan().then(function (obj) {
var now = Date.now();
var all = [];
for (var tag in obj) {
var raw = obj[tag];
if (typeof raw !== 'string') continue;
var rec;
try { rec = JSON.parse(raw); } catch (e) { continue; }
var s = Number(rec && rec.s);
if (!isFinite(s) || s < 0 || s > MAX_SCORE) continue;
var t = timeOf(tag, rec);
if (t > now + 60000) continue;
all.push({ tag: tag, name: String((rec && rec.n) || '匿名玩家').slice(0, 16), score: s, t: t });
}
all.sort(function (a, b) { return (b.t - a.t) || (b.tag > a.tag ? 1 : -1); });
var fresh = all.slice(0, WINDOW);
fresh.sort(function (a, b) { return (b.score - a.score) || (b.t - a.t); });
return fresh;
});
}
function cleanName(raw) {
var n = String(raw || '').replace(/[\u0000-\u001f\u007f]/g, '').trim();
if (n.length > 12) n = n.slice(0, 12);
return n;
}
function loadName() { try { return cleanName(localStorage.getItem(NAME_KEY) || ''); } catch (e) { return ''; } }
function saveName(n) { try { localStorage.setItem(NAME_KEY, n); } catch (e) {} }
function myName() { return loadName() || DEFAULT_NAME; }
var listEl = $('boardList'), modal = $('boardModal'), msgEl = $('submitMsg');
var nickInput = $('nickInput'), nameLabel = $('myNameLabel'), submitBtn = $('submitBtn'), submitBox = $('submitBox');
var lastSubmitAt = 0, submitting = false, pendingScore = 0;
function setMsg(text, kind) { if (!msgEl) return; msgEl.textContent = text || ''; msgEl.className = 'submit-msg' + (kind ? ' is-' + kind : ''); }
function showRetry(show) { if (submitBtn) submitBtn.hidden = !show; }
function paintName() { var n = myName(); if (nameLabel) nameLabel.textContent = n; if (nickInput && document.activeElement !== nickInput) nickInput.value = loadName(); }
function boardMessage(text) { if (!listEl) return; listEl.textContent = ''; var p = document.createElement('p'); p.className = 'board-empty'; p.textContent = text; listEl.appendChild(p); }
function rankClass(i) { return i === 0 ? 'r1' : i === 1 ? 'r2' : i === 2 ? 'r3' : ''; }
function renderBoard(rows, myScore) {
if (!listEl) return;
listEl.textContent = '';
if (!rows.length) { boardMessage('最近还没有人提交，快去玩一局！'); return; }
var marked = false;
rows.forEach(function (row, i) {
var line = document.createElement('div');
line.className = 'board-row ' + rankClass(i);
var rank = document.createElement('span'); rank.className = 'board-rank'; rank.textContent = i < 3 ? ['🥇', '🥈', '🥉'][i] : String(i + 1);
var name = document.createElement('span'); name.className = 'board-name'; name.textContent = row.name;
var score = document.createElement('span'); score.className = 'board-score'; score.textContent = row.score;
line.appendChild(rank); line.appendChild(name); line.appendChild(score);
if (!marked && myScore != null && row.score === myScore) { line.classList.add('is-mine'); marked = true; }
listEl.appendChild(line);
});
}
function refreshBoard(myScore) {
boardMessage('正在读取排行榜…');
return fetchTop().then(function (rows) { renderBoard(rows, myScore); return rows; }).catch(function (err) { boardMessage('读取失败：' + err.message + '（检查一下网络？）'); throw err; });
}
function openBoard() { if (!modal) return; modal.classList.add('show'); modal.setAttribute('aria-hidden', 'false'); refreshBoard(null).catch(function () {}); }
function closeBoard() { if (!modal) return; modal.classList.remove('show'); modal.setAttribute('aria-hidden', 'true'); }
function pushScore(name, score, viaRetry) {
if (submitting) return Promise.resolve(false);
if (!viaRetry) { var now = Date.now(); if (now - lastSubmitAt < MUTE_MIN_GAP) { setMsg('刚提交过啦，稍等一下', 'bad'); return Promise.resolve(false); } }
submitting = true; showRetry(false); setMsg('正在提交…', '');
return addScore(name, score).then(function () {
lastSubmitAt = Date.now();
setMsg('已上榜 ✓　' + name + ' · ' + score + ' 分', 'good');
return refreshBoard(score).then(function () { return true; }, function () { return true; });
}).catch(function (err) { setMsg('提交失败：' + err.message, 'bad'); showRetry(true); return false; }).then(function (ok) { submitting = false; return ok; });
}
function retry() { if (!pendingScore) return; pushScore(myName(), pendingScore, true); }
function onGameOver(score) {
if (!submitBox) return;
pendingScore = Number(score) || 0;
paintName(); showRetry(false);
if (!(pendingScore > 0)) { submitBox.style.display = 'none'; return; }
submitBox.style.display = ''; setMsg('正在结算…', ''); pushScore(myName(), pendingScore, true);
}
function bind() {
var boardBtn = $('boardBtn'); if (boardBtn) boardBtn.addEventListener('click', openBoard);
var boardBtn2 = $('boardBtn2'); if (boardBtn2) boardBtn2.addEventListener('click', openBoard);
var closeBtn = $('boardClose'); if (closeBtn) closeBtn.addEventListener('click', closeBoard);
var refreshBtn = $('boardRefresh'); if (refreshBtn) refreshBtn.addEventListener('click', function () { refreshBoard(null).catch(function () {}); });
if (modal) modal.addEventListener('click', function (e) { if (e.target === modal) closeBoard(); });
if (submitBtn) submitBtn.addEventListener('click', retry);
if (nickInput) {
nickInput.value = loadName();
var commit = function () { saveName(cleanName(nickInput.value)); nickInput.value = loadName(); paintName(); };
nickInput.addEventListener('change', commit);
nickInput.addEventListener('blur', commit);
nickInput.addEventListener('keydown', function (e) { if (e.key === 'Enter') { e.preventDefault(); commit(); nickInput.blur(); } });
}
var editNameBtn = $('editNameBtn');
if (editNameBtn) editNameBtn.addEventListener('click', function () { openBoard(); if (nickInput) setTimeout(function () { nickInput.focus(); nickInput.select(); }, 260); });
paintName();
window.addEventListener('keydown', function (e) { if (e.key === 'Escape') closeBoard(); });
}
if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', bind); else bind();
window.DanaiwaBoard = {
open: openBoard, close: closeBoard, refresh: refreshBoard,
onGameOver: onGameOver, fetchTop: fetchTop, submitScore: addScore,
myName: myName, setName: function (n) { saveName(cleanName(n)); paintName(); },
hasName: function () { return !!loadName(); }
};
})();
